    set res [r zrange points2{t} 0 -1 withscores]
    assert {[lindex $res 1] < 1}
    assert {[lindex $res 3] > 166}
    assert {[lindex $res 3] < 167}
}

test {GEORANGE STOREDIST option: COUNT ASC and DESC} {
    r del points{t}
