#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <limits.h>

static uint32_t digits10(uint64_t v) {
    if (v < 10) return 1;
    if (v < 100) return 2;
    if (v < 1000) return 3;
    if (v < 1000000000000UL) {
        if (v < 100000000UL) {
            if (v < 1000000) {
                if (v < 10000) return 4;
                return 5 + (v >= 100000);
            }
            return 7 + (v >= 10000000UL);
        }
        if (v < 10000000000UL) {
            return 9 + (v >= 1000000000UL);
        }
        return 11 + (v >= 100000000000UL);
    }
    return 12 + digits10(v / 1000000000000UL);
}

int fixedpoint_d2string(char *dst, size_t dstlen, double dvalue, int fractional_digits) {
    if (fractional_digits < 1 || fractional_digits > 17)
        goto err;
    if ((int)dstlen < (fractional_digits+3))
        goto err;
    if (dvalue == 0) {
        dst[0] = '0';
        dst[1] = '.';
        for (int i = 0; i < fractional_digits; i++) {
            dst[2 + i] = '0';
        }
        dst[fractional_digits+2] = '\0';
        return fractional_digits + 2;
    }
    static double powers_of_ten[] = {1.0, 10.0, 100.0, 1000.0, 10000.0, 100000.0, 1000000.0,
    10000000.0, 100000000.0, 1000000000.0, 10000000000.0, 100000000000.0, 1000000000000.0,
    10000000000000.0, 100000000000000.0, 1000000000000000.0, 10000000000000000.0,
    100000000000000000.0 };
    long long svalue = llrint(dvalue * powers_of_ten[fractional_digits]);
    unsigned long long value;
    int negative = 0;
    if (svalue < 0) {
        if (svalue != LLONG_MIN) {
            value = -svalue;
        } else {
            value = ((unsigned long long) LLONG_MAX)+1;
        }
        if (dstlen < 2)
            goto err;
        negative = 1;
        dst[0] = '-';
        dst++;
        dstlen--;
    } else {
        value = svalue;
    }

    static const char digitsd[201] =
        "0001020304050607080910111213141516171819"
        "2021222324252627282930313233343536373839"
        "4041424344454647484950515253545556575859"
        "6061626364656667686970717273747576777879"
        "8081828384858687888990919293949596979899";

    uint32_t ndigits = digits10(value);
    if (ndigits >= dstlen) goto err;
    int integer_digits = ndigits - fractional_digits;
    if (integer_digits < 1) {
        dst[0] = '0';
        integer_digits = 1;
    }
    dst[integer_digits] = '.';
    int size = integer_digits + 1 + fractional_digits;
    for (int i = integer_digits + 1; i < size - (int)ndigits; i++) {
        dst[i] = '0';
    }
    int next = size - 1;
    while (value >= 100) {
        int const i = (value % 100) * 2;
        value /= 100;
        dst[next] = digitsd[i + 1];
        dst[next - 1] = digitsd[i];
        next -= 2;
        if (next == integer_digits) {
            next--;
        }
    }

    if (value < 10) {
        dst[next] = '0' + (uint32_t) value;
    } else {
        int i = (uint32_t) value * 2;
        dst[next] = digitsd[i + 1];
        dst[next - 1] = digitsd[i];
    }
    dst[size] = '\0';
    return size + negative;
err:
    if (dstlen > 0)
        dst[0] = '\0';
    return 0;
}

int main(void) {
    char a[128], b[128];
    int bad = 0;
    for (int i = 0; i < 2000000; i++) {
        double v;
        if (i < 100000) {
            v = (double)i / 10000000.0;
        } else {
            uint64_t bits = ((uint64_t)rand() << 32) ^ rand();
            memcpy(&v, &bits, sizeof(v));
            if (!isfinite(v) || fabs(v) > 1e12) continue;
        }
        memset(a, 0xfc, sizeof(a));
        memset(b, 0, sizeof(b));
        int n = fixedpoint_d2string(a, sizeof(a), v, 4);
        snprintf(b, sizeof(b), "%.4f", v);
        if (n != (int)strlen(b) || strcmp(a, b)) {
            printf("MISMATCH v=%.17g got='%s' (n=%d) want='%s'\n", v, a, n, b);
            if (++bad > 20) return 1;
        }
    }
    printf("done bad=%d\n", bad);
    return 0;
}

